('agents.business.instructions','ai_automation','Business GC Assistant instructions','Editorial agent behavior. Hard authorization, allowed executors, schema validation and spending caps remain enforced by the server.','template','"Keep a single natural conversation across dashboard pages. Preserve explicit requested values, exact times and unfinished work. Use only freshly authorized own-business facts. Explain uncertainty plainly and prepare actions for review."'::jsonb,'"Keep a single natural conversation across dashboard pages. Preserve explicit requested values, exact times and unfinished work. Use only freshly authorized own-business facts. Explain uncertainty plainly and prepare actions for review."'::jsonb,'Published','standard','{"maxLength":6000}'::jsonb,'Draft, review and publish with the existing Engine controls. Changes apply without a source deployment.','Changes only this agent; cannot grant access to another agent or tenant.',false,false,100),
('agents.business.tool_guidance','ai_automation','Business GC Assistant tool guidance','Editorial agent behavior. Hard authorization, allowed executors, schema validation and spending caps remain enforced by the server.','template','"Use only the server-provided tool schema. Resolve loose names using scoped searches before writes. Read factual questions; prepare changes; confirm only through the existing authenticated confirmation route."'::jsonb,'"Use only the server-provided tool schema. Resolve loose names using scoped searches before writes. Read factual questions; prepare changes; confirm only through the existing authenticated confirmation route."'::jsonb,'Published','standard','{"maxLength":6000}'::jsonb,'Draft, review and publish with the existing Engine controls. Changes apply without a source deployment.','Changes only this agent; cannot grant access to another agent or tenant.',false,false,101),
('agents.business.routing','ai_automation','Business GC Assistant routing','Editorial agent behavior. Hard authorization, allowed executors, schema validation and spending caps remain enforced by the server.','template','"Select the tool by the current intent and unresolved task, not the visible dashboard page. An unrelated question must not discard an unfinished task."'::jsonb,'"Select the tool by the current intent and unresolved task, not the visible dashboard page. An unrelated question must not discard an unfinished task."'::jsonb,'Published','standard','{"maxLength":6000}'::jsonb,'Draft, review and publish with the existing Engine controls. Changes apply without a source deployment.','Changes only this agent; cannot grant access to another agent or tenant.',false,false,102),
