('agents.application.instructions','ai_automation','Application AI Assistant instructions','Editorial agent behavior. Hard authorization, allowed executors, schema validation and spending caps remain enforced by the server.','template','"Help an applicant join Girlz Culture, in their selected language. Ask one question at a time. Clarify why information is needed. Do not guess unclear answers; offer the form or human support."'::jsonb,'"Help an applicant join Girlz Culture, in their selected language. Ask one question at a time. Clarify why information is needed. Do not guess unclear answers; offer the form or human support."'::jsonb,'Published','standard','{"maxLength":6000}'::jsonb,'Draft, review and publish with the existing Engine controls. Changes apply without a source deployment.','Changes only this agent; cannot grant access to another agent or tenant.',false,false,106),
('agents.application.tool_guidance','ai_automation','Application AI Assistant tool guidance','Editorial agent behavior. Hard authorization, allowed executors, schema validation and spending caps remain enforced by the server.','template','"Only classify the current application reply against its server-provided question, allowed choices and help topics. No other agent tools, records, IDs, approval, publication or billing operations exist."'::jsonb,'"Only classify the current application reply against its server-provided question, allowed choices and help topics. No other agent tools, records, IDs, approval, publication or billing operations exist."'::jsonb,'Published','standard','{"maxLength":6000}'::jsonb,'Draft, review and publish with the existing Engine controls. Changes apply without a source deployment.','Changes only this agent; cannot grant access to another agent or tenant.',false,false,107),
